package com.duckblade.osrs.toa.features.pointstracker;

import com.duckblade.osrs.toa.TombsOfAmascutConfig;
import com.duckblade.osrs.toa.module.PluginLifecycleComponent;
import com.duckblade.osrs.toa.util.RaidState;
import com.duckblade.osrs.toa.util.RaidStateTracker;
import com.google.common.annotations.VisibleForTesting;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PurpleWeightingManager implements PluginLifecycleComponent
{

	private static final Map<Purple, Integer> BASE_WEIGHTS = new EnumMap<>(Map.of(
		Purple.OSMUMTENS_FANG, 70,
		Purple.LIGHTBEARER, 70,
		Purple.ELIDINIS_WARD, 30,
		Purple.MASORI_MASK, 20,
		Purple.MASORI_BODY, 20,
		Purple.MASORI_CHAPS, 20,
		Purple.TUMEKENS_SHADOW, 10
	));

	public static class PurpleWeightChanged
	{
	}

	@Value
	static class PurpleWeighting
	{
		int weight;
		double purplePercent;
		double pointsAdjustedPercent;
	}

	private final EventBus eventBus;
	private final Client client;
	private final RaidStateTracker raidStateTracker;
	private final PointsTracker pointsTracker;

	private final Map<Purple, Integer> weights = new EnumMap<>(BASE_WEIGHTS);

	@VisibleForTesting
	int raidLevel = 0;

	private int lastWeightedRaidLevel = 0;
	private int weightSum = 0;

	@Override
	public boolean isEnabled(TombsOfAmascutConfig config, RaidState raidState)
	{
		// always on so we can detect raid level from party board, even if the overlays are currently off
		return true;
	}

	@Override
	public void startUp()
	{
		eventBus.register(this);
	}

	@Override
	public void shutDown()
	{
		eventBus.unregister(this);
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		lastWeightedRaidLevel = -1;
		updateRaidLevel();
		reweight();
	}

	PurpleWeighting getWeighting(Purple purple)
	{
		int weight = weights.get(purple);
		double rate = (double) weight / weightSum;
		double ptsRate = rate * pointsTracker.getUniqueChance();

		return new PurpleWeighting(weight, rate, ptsRate);
	}

	private void updateRaidLevel()
	{
		int raidLevel = -1;
		if (raidStateTracker.getCurrentState().isInRaid())
		{
			raidLevel = client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL);
		}
		else
		{
			Widget partyBoardWidget = client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL);
			if (partyBoardWidget != null)
			{
				raidLevel =
					Integer.parseInt(
						partyBoardWidget.getText()
							.split(":")[1]
							.split("<")[0]
							.strip()
					);
			}
		}

		if (raidLevel >= 0 && this.raidLevel != (this.raidLevel = raidLevel))
		{
			log.debug("New raid level: {}", this.raidLevel);
		}
	}

	void reweight()
	{
		if (this.lastWeightedRaidLevel == this.raidLevel)
		{
			return;
		}

		weights.put(Purple.LIGHTBEARER, BASE_WEIGHTS.get(Purple.LIGHTBEARER) - lerpClamped(this.raidLevel, 450, 500, 5));
		weights.put(Purple.LIGHTBEARER, weights.get(Purple.LIGHTBEARER) - lerpClamped(this.raidLevel, 300, 450, 30));

		weights.put(Purple.OSMUMTENS_FANG, BASE_WEIGHTS.get(Purple.OSMUMTENS_FANG) - lerpClamped(this.raidLevel, 450, 500, 10));
		weights.put(Purple.OSMUMTENS_FANG, weights.get(Purple.OSMUMTENS_FANG) - lerpClamped(this.raidLevel, 350, 400, 20));
		weights.put(Purple.OSMUMTENS_FANG, weights.get(Purple.OSMUMTENS_FANG) - lerpClamped(this.raidLevel, 300, 350, 10));

		if (this.raidLevel >= 50 && this.raidLevel < 150)
		{
			// between 50-149, ward+masori+shadow are reduced with an additional 1/50 roll
			// simulate reducing everything else by 50x by instead increasing these two by 50x
			weights.put(Purple.LIGHTBEARER, BASE_WEIGHTS.get(Purple.LIGHTBEARER) * 50);
			weights.put(Purple.OSMUMTENS_FANG, BASE_WEIGHTS.get(Purple.OSMUMTENS_FANG) * 50);
		}

		this.lastWeightedRaidLevel = this.raidLevel;
		this.weightSum = weights.values()
			.stream()
			.reduce(0, Integer::sum);

		eventBus.post(new PurpleWeightChanged());
	}

	private int lerpClamped(int raidLevel, int raidLevelMin, int raidLevelMax, int weightRange)
	{
		if (raidLevel <= raidLevelMin)
		{
			return 0;
		}
		else if (raidLevel >= raidLevelMax)
		{
			return weightRange;
		}

		return (weightRange) * (raidLevel - raidLevelMin) / (raidLevelMax - raidLevelMin);
	}
}

package com.duckblade.osrs.toa.features.pointstracker;

import com.duckblade.osrs.toa.TombsOfAmascutConfig;
import com.duckblade.osrs.toa.module.PluginLifecycleComponent;
import com.duckblade.osrs.toa.util.RaidState;
import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PurpleWeightingPartyBoardManager implements PluginLifecycleComponent
{

	private static final int SCRIPT_INIT_LOOT_REWARDS = 6770;

	private final EventBus eventBus;

	private final Client client;
	private final PurpleWeightingManager weightingManager;

	@Override
	public boolean isEnabled(TombsOfAmascutConfig config, RaidState raidState)
	{
		return raidState.isInLobby() &&
			config.purpleWeightingDisplayOnPartyBoard();
	}

	@Override
	public void startUp()
	{
		installToWidget();
		eventBus.register(this);
	}

	@Override
	public void shutDown()
	{
		widgetUninstall();
		eventBus.unregister(this);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired e)
	{
		if (e.getScriptId() == SCRIPT_INIT_LOOT_REWARDS)
		{
			installToWidget();
		}
	}

	@Subscribe
	public void onPurpleWeightChanged(PurpleWeightingManager.PurpleWeightChanged e)
	{
		installToWidget();
	}

	private void installToWidget()
	{
		Widget lootContainer = client.getWidget(InterfaceID.ToaPartydetails.RAID_LOOT_POTENTIAL);
		Widget[] lootChildren;
		if (lootContainer == null || (lootChildren = lootContainer.getChildren()) == null)
		{
			return;
		}

		// remove the previous %s since the script doesn't fully rebuild the widget
		widgetUninstall();

		for (Widget child : lootChildren)
		{
			Purple purple = Purple.forItemId(child.getItemId());
			if (purple == null)
			{
				continue;
			}

			PurpleWeightingManager.PurpleWeighting weighting = weightingManager.getWeighting(purple);
			lootContainer.createChild(-1, WidgetType.TEXT)
				.setText(String.format("%.1f%%", weighting.getPurplePercent() * 100))
				.setFontId(FontID.PLAIN_11)
				.setXTextAlignment(WidgetTextAlignment.CENTER)
				.setYTextAlignment(WidgetTextAlignment.BOTTOM)
				.setTextShadowed(true)
				.setTextColor(Color.white.getRGB())
				.setSize(child.getOriginalWidth(), child.getOriginalHeight(), child.getWidthMode(), child.getHeightMode())
				.setPos(child.getOriginalX(), child.getOriginalY(), child.getXPositionMode(), child.getYPositionMode())
				.revalidate();
		}
	}

	private void widgetUninstall()
	{
		Widget lootContainer = client.getWidget(InterfaceID.ToaPartydetails.RAID_LOOT_POTENTIAL);
		Widget[] lootChildren;
		if (lootContainer == null || (lootChildren = lootContainer.getChildren()) == null)
		{
			return;
		}

		for (int i = 0; i < lootChildren.length; i++)
		{
			if (lootChildren[i].getText().contains("%"))
			{
				lootChildren[i] = null;
			}
		}
	}
}

package com.duckblade.osrs.toa.features.pointstracker;

import lombok.experimental.UtilityClass;

@UtilityClass
public class UniqueChanceCalculator
{

	private static final int BASE_RATE_UNIQUE = 10_500;
	private static final int MODIFIER_RAID_LEVEL_UNIQUE = 20;

	private static final int BASE_RATE_PET = 350_000;
	private static final int MODIFIER_RAID_LEVEL_PET = 700;

	private static final int PURPLE_DIMINISH_POINT_1 = 310;
	private static final int PURPLE_DIMINISH_FACTOR_1 = 3;
	private static final int PURPLE_DIMINISH_POINT_2 = 430;
	private static final int PURPLE_DIMINISH_FACTOR_2 = 2;
	private static final int PET_DIMINISH_POINT_1 = 400;
	private static final int PET_DIMINISH_FACTOR_1 = 3;
	private static final int RAID_LEVEL_MAX = 550;

	private static final double MAX_RATE_UNIQUE = 55.0;

	public static double getUniqueChance(int raidLevel, int points)
	{
		raidLevel = Math.min(RAID_LEVEL_MAX, raidLevel);
		if (raidLevel > PURPLE_DIMINISH_POINT_1)
		{
			if (raidLevel > PURPLE_DIMINISH_POINT_2)
			{
				raidLevel = PURPLE_DIMINISH_POINT_2 + ((raidLevel - PURPLE_DIMINISH_POINT_2) / PURPLE_DIMINISH_FACTOR_2);
			}
			raidLevel = PURPLE_DIMINISH_POINT_1 + ((raidLevel - PURPLE_DIMINISH_POINT_1) / PURPLE_DIMINISH_FACTOR_1);
		}

		return getChance(raidLevel, points, BASE_RATE_UNIQUE, MODIFIER_RAID_LEVEL_UNIQUE);
	}

	public static double getPetChance(int raidLevel, int points)
	{
		raidLevel = Math.min(RAID_LEVEL_MAX, raidLevel);
		if (raidLevel > PET_DIMINISH_POINT_1)
		{
			raidLevel = PET_DIMINISH_POINT_1 + ((raidLevel - PET_DIMINISH_POINT_1) / PET_DIMINISH_FACTOR_1);
		}

		return getChance(raidLevel, points, BASE_RATE_PET, MODIFIER_RAID_LEVEL_PET);
	}

	private static double getChance(int raidLevel, int points, int baseRate, int modifier)
	{
		double denominator = baseRate - (modifier * raidLevel);
		return Math.max(0, Math.min(MAX_RATE_UNIQUE, points / denominator)) / 100.0;
	}
}

