		BIRD(6, ObjectID.TOA_SCABARAS_TOTALTILES_TILE6, ObjectID.TOA_SCABARAS_FX10),
		CROOK(7, ObjectID.TOA_SCABARAS_TOTALTILES_TILE7, ObjectID.TOA_SCABARAS_FX03),
