package com.duckblade.osrs.toa.util;

import net.runelite.api.Actor;

public final class NpcUtil
{
	private NpcUtil()
	{
	}

	/**
	 * Calculates Actor's current hitpoints
	 * <p>
	 * Adapted from RuneLite OpponentInfo Plugin
	 *
	 * @param actor the actor
	 * @param maxHp the actor's max hp
	 * @return the actor's current hp, else -1
	 */
	public static int calculateActorHp(final Actor actor, final int maxHp)
	{
		final int scale = actor.getHealthScale();
		final int ratio = actor.getHealthRatio();

		if (scale <= 0 || ratio < 0)
		{
			return -1;
		}

		int health = 0;

		if (ratio > 0)
		{
			int minHealth = 1;
			int maxHealth;

			if (scale > 1)
			{
				if (ratio > 1)
				{
					minHealth = (maxHp * (ratio - 1) + scale - 2) / (scale - 1);
				}

				maxHealth = (maxHp * ratio - 1) / (scale - 1);

				if (maxHealth > maxHp)
				{
					maxHealth = maxHp;
				}
			}
			else
			{
				maxHealth = maxHp;
			}

			health = (minHealth + maxHealth + 1) / 2;
		}

		return health;
	}
}

package com.duckblade.osrs.toa.util;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import lombok.experimental.UtilityClass;
import net.runelite.api.Point;
import java.awt.Shape;
import java.awt.Stroke;

@UtilityClass
public final class OverlayUtil
{

	public static void drawOutlineAndFill(final Graphics2D graphics2D, final Color outlineColor, final Color fillColor, final float strokeWidth, final Shape shape)
	{
		final Color originalColor = graphics2D.getColor();
		final Stroke originalStroke = graphics2D.getStroke();

		graphics2D.setStroke(new BasicStroke(strokeWidth));
		graphics2D.setColor(outlineColor);
		graphics2D.draw(shape);

		graphics2D.setColor(fillColor);
		graphics2D.fill(shape);

		graphics2D.setColor(originalColor);
		graphics2D.setStroke(originalStroke);
	}

	public static void renderTextLocation(final Graphics2D graphics2D, final Point point, final String text, final Color color, final int size, final int style, final boolean shadow)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}

		final Color origColor = graphics2D.getColor();
		final Font origFont = graphics2D.getFont();

		graphics2D.setFont(new Font(null, style, size));

		if (shadow)
		{
			graphics2D.setColor(Color.BLACK);
			graphics2D.drawString(text, point.getX() + 1, point.getY() + 1);
		}

		graphics2D.setColor(color);
		graphics2D.drawString(text, point.getX(), point.getY());

		graphics2D.setFont(origFont);
		graphics2D.setColor(origColor);
	}

}

package com.duckblade.osrs.toa.util;

import java.awt.Polygon;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

public class PolygonUtil
{

	public static Polygon rotate(Polygon poly, double thetaRadians)
	{
		double sin = Math.sin(thetaRadians);
		double cos = Math.cos(thetaRadians);

		Polygon ret = new Polygon(new int[poly.npoints], new int[poly.npoints], poly.npoints);
		for (int i = 0; i < poly.npoints; i++)
		{
			double x = poly.xpoints[i];
			double y = poly.ypoints[i];
			ret.xpoints[i] = (int) Math.round(x * cos - y * sin);
			ret.ypoints[i] = (int) Math.round(x * sin + y * cos);
		}
		return ret;
	}

	public static Polygon localPointTranspose(LocalPoint localOrigin, Polygon poly)
	{
		Polygon ret = new Polygon(new int[poly.npoints], new int[poly.npoints], poly.npoints);
		for (int i = 0; i < poly.npoints; i++)
		{
			ret.xpoints[i] = localOrigin.getX() + poly.xpoints[i];
			ret.ypoints[i] = localOrigin.getY() + poly.ypoints[i];
		}
		return ret;
	}

	public static Polygon toCanvas(Client client, WorldView wv, Polygon poly)
	{
		Polygon ret = new Polygon(new int[poly.npoints], new int[poly.npoints], poly.npoints);
		for (int i = 0; i < poly.npoints; i++)
		{
			LocalPoint lp = new LocalPoint(poly.xpoints[i], poly.ypoints[i], wv);
			Point canvas = Perspective.localToCanvas(
				client,
				lp,
				wv.getPlane()
			);

			if (canvas == null)
			{
				return null;
			}
			ret.xpoints[i] = canvas.getX();
			ret.ypoints[i] = canvas.getY();
		}
		return ret;
	}

}

package com.duckblade.osrs.toa.util;

import com.duckblade.osrs.toa.module.PluginLifecycleComponent;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RaidCompletionTracker implements PluginLifecycleComponent
{

	private final EventBus eventBus;

	private final Set<String> completedBosses = new HashSet<>();

	@Override
	public void startUp()
	{
		eventBus.register(this);
	}

	@Override
	public void shutDown()
	{
		eventBus.unregister(this);
	}

	@Subscribe(priority = Float.MAX_VALUE)
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		if (e.getMessage().startsWith("Challenge complete: "))
		{
			String bossName = e.getMessage()
				.substring("Challenge complete: ".length(), e.getMessage().indexOf('.'));
			completedBosses.add(bossName);
		}
	}

	@Subscribe
	public void onRaidStateChanged(RaidStateChanged e)
	{
		if (!e.getNewState().isInRaid())
		{
			completedBosses.clear();
		}
	}

	public Set<String> getCompletedBosses()
	{
		return Collections.unmodifiableSet(completedBosses);
	}

}

